/**
 * Checks that the SEO surface is wired up and actually serving.
 *
 * The sitemap and robots.txt are generated by Next's own file conventions now
 * (app/sitemap.ts, app/robots.ts) rather than by hand-rolled route handlers,
 * so this verifies the generators are present and — against a running site —
 * that what they produce is fetchable and lists the story pages.
 *
 *   yarn verify-seo                        # source check only
 *   CHECK_URL=http://localhost:3000 yarn verify-seo
 *   CHECK_URL=https://dicom.gouni.edu.ng yarn verify-seo
 */
const fs = require("fs");
const path = require("path");

const REQUIRED_FILES = [
  ["app/sitemap.ts", "sitemap generator"],
  ["app/robots.ts", "robots.txt generator"],
  ["app/api/revalidate/route.ts", "on-demand revalidation endpoint"],
  ["lib/structured-data.tsx", "JSON-LD schemas"],
];

let failed = false;

function fail(message) {
  console.error(`✗ ${message}`);
  failed = true;
}

function verifySources() {
  console.log("Verifying SEO sources...");

  for (const [file, label] of REQUIRED_FILES) {
    if (fs.existsSync(path.join(process.cwd(), file))) {
      console.log(`✓ ${label} (${file})`);
    } else {
      fail(`Missing ${label}: ${file}`);
    }
  }
}

async function verifyServed(baseUrl) {
  console.log(`\nVerifying served output at ${baseUrl}...`);

  const robots = await fetch(`${baseUrl}/robots.txt`);
  if (!robots.ok) return fail(`robots.txt returned ${robots.status}`);

  const robotsBody = await robots.text();
  if (!robotsBody.includes("Sitemap:")) {
    fail("robots.txt does not point at a sitemap");
  } else {
    console.log("✓ robots.txt is served and references the sitemap");
  }

  const sitemap = await fetch(`${baseUrl}/sitemap.xml`);
  if (!sitemap.ok) return fail(`sitemap.xml returned ${sitemap.status}`);

  const sitemapBody = await sitemap.text();
  if (!sitemapBody.includes("<urlset")) {
    return fail("sitemap.xml is not a urlset document");
  }

  const urls = sitemapBody.match(/<loc>([^<]+)<\/loc>/g) ?? [];
  const stories = urls.filter((url) => url.includes("/achievements/"));
  console.log(`✓ sitemap.xml lists ${urls.length} URLs (${stories.length} stories)`);

  if (stories.length === 0) {
    fail("sitemap.xml lists no achievement stories");
  }
}

async function main() {
  console.log("Starting SEO setup verification...\n");

  verifySources();

  const baseUrl = process.env.CHECK_URL;
  if (baseUrl) {
    await verifyServed(baseUrl.replace(/\/$/, ""));
  } else {
    console.log("\nSet CHECK_URL to also verify a running site.");
  }

  if (failed) {
    console.error("\nSEO setup verification failed.");
    process.exit(1);
  }

  console.log("\nSEO setup verification completed!");
}

main();
